class Solution {
public:
    int countLatticePoints(vector<vector<int>>& circles) {
        set<pair<int,int>> seen;
        for (auto& c : circles)
            for (int px = c[0]-c[2]; px <= c[0]+c[2]; px++)
                for (int py = c[1]-c[2]; py <= c[1]+c[2]; py++)
                    if ((long long)(px-c[0])*(px-c[0]) + (long long)(py-c[1])*(py-c[1]) <= (long long)c[2]*c[2])
                        seen.insert({px, py});
        return seen.size();
    }
};

