class Solution:
    def countLatticePoints(self, circles: List[List[int]]) -> int:
        from collections import defaultdict
        import math
        rows = defaultdict(list)
        for x, y, r in circles:
            for py in range(y - r, y + r + 1):
                d = math.isqrt(r * r - (py - y) ** 2)
                rows[py].append((x - d, x + d))
        ans = 0
        for ivs in rows.values():
            ivs.sort()
            cs, ce = ivs[0]
            for a, b in ivs[1:]:
                if a > ce:
                    ans += ce - cs + 1
                    cs, ce = a, b
                else:
                    ce = max(ce, b)
            ans += ce - cs + 1
        return ans

