class Solution {
public:
    int countLatticePoints(vector<vector<int>>& circles) {
        unordered_map<int, vector<pair<int,int>>> rows;
        for (auto& c : circles)
            for (int py = c[1]-c[2]; py <= c[1]+c[2]; py++) {
                int d = sqrt((double)c[2]*c[2] - (double)(py-c[1])*(py-c[1]) + 1e-9);
                rows[py].push_back({c[0]-d, c[0]+d});
            }
        int ans = 0;
        for (auto& [y, ivs] : rows) {
            sort(ivs.begin(), ivs.end());
            int cs = ivs[0].first, ce = ivs[0].second;
            for (int i = 1; i < ivs.size(); i++) {
                if (ivs[i].first > ce) { ans += ce - cs + 1; cs = ivs[i].first; ce = ivs[i].second; }
                else ce = max(ce, ivs[i].second);
            }
            ans += ce - cs + 1;
        }
        return ans;
    }
};

