class Solution {
    public int countLatticePoints(int[][] circles) {
        Map<Integer, List<int[]>> rows = new HashMap<>();
        for (int[] c : circles)
            for (int py = c[1]-c[2]; py <= c[1]+c[2]; py++) {
                int d = (int)Math.sqrt((double)c[2]*c[2] - (double)(py-c[1])*(py-c[1]) + 1e-9);
                rows.computeIfAbsent(py, z -> new ArrayList<>()).add(new int[]{c[0]-d, c[0]+d});
            }
        int ans = 0;
        for (List<int[]> ivs : rows.values()) {
            ivs.sort((a, b) -> a[0] - b[0]);
            int cs = ivs.get(0)[0], ce = ivs.get(0)[1];
            for (int i = 1; i < ivs.size(); i++) {
                if (ivs.get(i)[0] > ce) { ans += ce - cs + 1; cs = ivs.get(i)[0]; ce = ivs.get(i)[1]; }
                else ce = Math.max(ce, ivs.get(i)[1]);
            }
            ans += ce - cs + 1;
        }
        return ans;
    }
}

