var countLatticePoints = function(circles) {
    const rows = new Map();
    for (const [x, y, r] of circles)
        for (let py = y - r; py <= y + r; py++) {
            const d = Math.floor(Math.sqrt(r*r - (py-y)*(py-y) + 1e-9));
            if (!rows.has(py)) rows.set(py, []);
            rows.get(py).push([x - d, x + d]);
        }
    let ans = 0;
    for (const ivs of rows.values()) {
        ivs.sort((a, b) => a[0] - b[0]);
        let [cs, ce] = ivs[0];
        for (let i = 1; i < ivs.length; i++) {
            if (ivs[i][0] > ce) { ans += ce - cs + 1; [cs, ce] = ivs[i]; }
            else ce = Math.max(ce, ivs[i][1]);
        }
        ans += ce - cs + 1;
    }
    return ans;
};
